    const directoryArtifacts = join(root, "debate-directory-artifacts");
    const linkedChildTarget = join(outside, "debate-real-child");
    await Promise.all([
      mkdir(complete),
      mkdir(linkedArtifacts),
      mkdir(directoryArtifacts),
