test("readDebateArtifact returns exact UTF-8 artifacts and the same highest determination catalog selects", async () => {
  const { base, root } = await fixture();
  try {
    const debate = join(root, "debate-readable");
    const transcript = "  opening\n\nλ ≠ \ud83d\ude80\n";
    const determination = "\nSTATUS: NEEDS_INPUT\r\n  ¿qué sigue?\r\n";
    await mkdir(debate);
    await Promise.all([
      writeFile(join(debate, "debate.md"), transcript),
      writeFile(join(debate, "respondeo-2.md"), "STATUS: RESOLVED"),
      writeFile(join(debate, "respondeo-10.md"), determination),
      writeFile(join(debate, "final-report.md"), ""),
    ]);

    assert.equal(await readDebateArtifact(root, "debate-readable", "transcript"), transcript);
    assert.equal(await readDebateArtifact(root, "debate-readable", "determination"), determination);
    assert.equal(await readDebateArtifact(root, "debate-readable", "final-report"), "");
    const [entry] = await listDebates(root);
    assert.equal(entry.determination, "respondeo-10.md");
  } finally {
    await rm(base, { recursive: true, force: true });
  }
});

