test("finalize: budget-exhausted redactio sets finalReportError.budgetExhausted", async () => {
  const budgetFail = (error: string): AgentResult => ({ ok: false, error, budgetExhausted: true });
  const a = fake("a", "v1", async () => ok("proposal A"));
