// Orchestration (Kaizen v0): a crude round-robin debate that accumulates into one
// markdown transcript. No scholastic protocol / respondeo / eval yet — those are the
// next small steps. This is the smallest thing that reproduces the manual workflow.

import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import type { Participant, AgentResult } from "./adapters.ts";

const execFileAsync = promisify(execFile);

function log(msg: string) { console.error(`[disputatio] ${msg}`); }

export type Turn = { title: string; participant: string; result: AgentResult };

export type RespondeoStatus = "RESOLVED" | "NEEDS_INPUT" | "FAILED";

export type DebateOutcome = {
  transcript: string;       // the full markdown artifact (incl. cost footnotes, failure details)
  turns: Turn[];            // per-turn results, raw CLI captures attached (diagnostics)
  aborted?: string;         // set when the debate could not proceed (e.g. <2 proposals)
  respondeo?: {             // the judge's consolidatio (only when a judge ran)
    status: RespondeoStatus;
    text: string;           // the verdict body — written verbatim to respondeo.md
  };
  finalReport?: {           // the redactio: the deliverable, only when respondeo RESOLVED
    text: string;           // written verbatim to final-report.md
  };
  finalReportError?: {      // set when the redactio ran but failed (debate + verdict still succeeded)
    budgetExhausted: boolean;
    message: string;
  };
};

// Transcript view (for the .md artifact): keeps cost + failure detail.
function render(title: string, r: AgentResult): string {
  if (r.ok) {
    const cost = r.costUsd ? `\n\n_(cost: $${r.costUsd.toFixed(4)})_` : "";
    return `## ${title}\n\n${r.text}${cost}\n`;
  }
  return `## ${title}\n\n> ⚠️ FAILED: ${r.error}\n`;
}

// Prompt-context view (fed back to agents): no cost footnotes, no raw error
// dumps — keep the context agents reason over clean and a little smaller.
function renderForContext(title: string, r: AgentResult): string {
  if (r.ok) return `## ${title}\n\n${r.text}\n`;
  return `## ${title}\n\n> (this participant produced no contribution this turn)\n`;
}

// git worktree add/remove on the same repo can contend on .git locks when run
// concurrently — serialize the git operations (NOT the agent runs).
let gitLock: Promise<unknown> = Promise.resolve();
function withGitLock<T>(fn: () => Promise<T>): Promise<T> {
  const p = gitLock.then(fn, fn);
  gitLock = p.then(() => {}, () => {});
  return p;
}

// Run a participant in ISOLATION. Isolation is a correctness requirement:
// - Without repoPath: a throwaway temp dir, so agentic CLIs like agy cannot read
//   sibling files — the contamination we caught in research/pre-m0-handrun.md.
// - With repoPath: a DETACHED, THROWAWAY git worktree of HEAD — never the real
//   checkout. Real-run lesson: evidence commands can write local runtime artifacts
//   into the target repo. In a worktree those writes land in the disposable copy
//   and die with it. Trade-off: agents see HEAD only (uncommitted changes are invisible) and
//   untracked build artifacts (node_modules, …) are absent.
export async function runIsolated(p: Participant, prompt: string, repoPath?: string): Promise<AgentResult> {
  const dir = await mkdtemp(join(tmpdir(), "disputatio-"));
  try {
    if (!repoPath) return await p.run(prompt, dir);
    const wt = join(dir, "wt");
    await withGitLock(() => execFileAsync("git", ["-C", repoPath, "worktree", "add", "--detach", wt, "HEAD"]));
    try {
      return await p.run(prompt, wt);
    } finally {
      await withGitLock(async () => {
        try { await execFileAsync("git", ["-C", repoPath, "worktree", "remove", "--force", wt]); }
        catch { /* dir removal below + git's own prune cover the rest */ }
      });
    }
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
}

const proposePrompt = (task: string) =>
  `You are one independent reviewer in a structured debate. The task:\n\n${task}\n\n` +
  `Give your honest, concrete, opinionated proposal/answer. If a repository or files are present in your ` +
  `working directory and relevant, READ them and run READ-ONLY commands (e.g. run the existing tests) to ` +
  `ground your reasoning in real evidence. Respond in English, concise.`;

const reactPrompt = (ctx: string, me: string) =>
  `You are "${me}", one reviewer in a structured debate. The full debate so far:\n\n${ctx}\n\n` +
  `React adversarially: where do you AGREE, where do you DISAGREE (find real, specific flaws), and what is ` +
  `MISSING? State any objection you can back with EXECUTABLE EVIDENCE (run a test, check a file/API in your ` +
  `working directory). Do not repeat what has already been said. Respond in English, concise.`;

// Respondeo: the judge renders the consolidatio over the transcript ALONE (no repo
// access, even in repo mode). It must ASK rather than guess — if a contested point
// cannot be resolved from the transcript, it emits questions for the human instead of
// fabricating a ruling. The mandatory first STATUS line is the machine signal index.ts
// parses to surface NEEDS_INPUT.
const respondeoPrompt = (ctx: string) =>
  `You are the JUDGE (respondeo) closing a structured debate. The full transcript:\n\n${ctx}\n\n` +
  `Render the consolidatio — the resolution. You reason over THIS TRANSCRIPT ALONE; you have no repository ` +
  `access. Rules:\n` +
  `1. Your FIRST line must be exactly one of: "STATUS: RESOLVED" or "STATUS: NEEDS_INPUT" (nothing else on it).\n` +
  `2. Then record the SETTLED AGREEMENTS (what every participant converged on).\n` +
  `3. Then rule on each CONTESTED point, weighing the arguments — prefer positions backed by executable ` +
  `evidence over rhetoric.\n` +
  `4. If — and only if — one or more contested points genuinely CANNOT be resolved from the transcript ` +
  `without human input, use STATUS: NEEDS_INPUT, still record the settled agreements, then add a final ` +
  `"## Quaestiones (for the human)" list of the specific questions, and issue NO ruling on those points. ` +
  `Do not invent a verdict you cannot defend from the transcript.\n` +
  `Respond in English, concise, in Markdown.`;

// Only an explicit STATUS: NEEDS_INPUT on the first non-empty line triggers the human
// path; anything else from a successful turn (RESOLVED or a missing/garbled marker)
// is a verdict. A failed turn is classified FAILED by the caller. Exported because
// --continue / --finalize parse a respondeo loaded back from disk (index.ts).
export function parseRespondeoStatus(text: string): "RESOLVED" | "NEEDS_INPUT" {
  const first = text.split("\n").map((l) => l.trim()).find((l) => l !== "") ?? "";
  return /^STATUS:\s*NEEDS_INPUT\b/i.test(first) ? "NEEDS_INPUT" : "RESOLVED";
}

// Redactio — the SYNTHESIZER authors the actual deliverable the debate existed to
// produce (the plan / review / proposal / outline the user will execute), NOT a
// summary of who-said-what. This is the gap real use surfaced: respondeo.md holds the
// RULING ON the debate, not the work-product born FROM it, so it lacks the data needed
// to start the work. Transcript-only like respondeo: the debate already gathered the
// evidence and it lives in the transcript (repo-grounded redactio is a follow-up).
const finalizePrompt = (quaestio: string, transcript: string, determination: string) =>
  `You are the SYNTHESIZER closing a structured debate. Author the FINAL DELIVERABLE the ` +
  `debate existed to produce — the document a human or agent will use to START THE WORK ` +
  `(implement, review, present, propose). This is the product, NOT minutes of the debate.\n\n` +
  `The original quaestio (it fixes the deliverable's PURPOSE and shape):\n\n${quaestio}\n\n` +
  `The full debate transcript (proposals, reactions, evidence):\n\n${transcript}\n\n` +
  `The respondeo — the judge's determination (what was settled, what was ruled, and why):\n\n${determination}\n\n` +
  `Rules:\n` +
  `1. Infer the deliverable TYPE from the quaestio (implementation plan, code-review report, ` +
  `proposal, presentation outline, …) and produce THAT artifact, in its natural shape.\n` +
  `2. Build it from the SETTLED decisions in the respondeo: adopt what won, drop what was ` +
  `rejected, and fold in the evidence that backed the winning positions.\n` +
  `3. If a repository is present in your working directory, READ it and run READ-ONLY ` +
  `commands to ground the deliverable in the REAL files — prefer concrete, file-accurate ` +
  `steps (real paths, real current shapes) over generic ones. (No repo present = work from ` +
  `the transcript alone.)\n` +
  `4. Make it SELF-CONTAINED: someone reading ONLY this document must have everything needed ` +
  `to begin — restate the context and decisions; never say "as discussed above".\n` +
  `5. Leave the debate's blow-by-blow OUT; keep a rationale only where it is load-bearing for execution.\n` +
  `6. If the respondeo left points unresolved, end with a short "## Open points" section so they ` +
  `are not lost — but do not block the deliverable on them.\n` +
  `Respond in English, in Markdown.`;

// Continuation (--continue): the human has answered the respondeo's open questions.
// Re-invoke the JUDGE ALONE (the cheap path) with the transcript + prior determination
// + the answers. If the answers merely DISAMBIGUATE points the debaters already argued,
// the judge can now rule (RESOLVED). If they open genuinely NEW ground nobody argued,
// the judge must NOT invent a verdict — it returns NEEDS_INPUT again, which is the
// signal that a fresh reaction round is needed (re-debate is the documented follow-up).
const continuePrompt = (quaestio: string, transcript: string, previousDetermination: string, humanAnswers: string) =>
  `You are the JUDGE (respondeo) RESUMING a structured debate you previously could not fully ` +
  `resolve. You reason over the TRANSCRIPT and your PRIOR determination ALONE — no repository ` +
  `access. The human has now answered your open questions.\n\n` +
  `The original quaestio:\n\n${quaestio}\n\n` +
  `The full debate transcript:\n\n${transcript}\n\n` +
  `Your PRIOR determination (it ended in NEEDS_INPUT):\n\n${previousDetermination}\n\n` +
  `The human's answers to your open questions:\n\n${humanAnswers}\n\n` +
  `Rules:\n` +
  `1. Your FIRST line must be exactly one of: "STATUS: RESOLVED" or "STATUS: NEEDS_INPUT".\n` +
  `2. Resolve every point you previously left open, USING the human's answers. Do not re-ask ` +
  `what they have already answered.\n` +
  `3. Carry forward the settled agreements and prior rulings that still hold.\n` +
  `4. ONLY if the answers open a genuinely NEW question the debaters never argued, which you ` +
  `cannot settle from the transcript without inventing a verdict, use STATUS: NEEDS_INPUT, ` +
  `record what is now settled, and list ONLY the new "## Quaestiones (for the human)". ` +
  `Do not fabricate a verdict you cannot defend from the transcript.\n` +
  `Respond in English, concise, in Markdown.`;

// The redactio turn: author the deliverable from a RESOLVED determination. UNLIKE the
// respondeo (which is transcript-only by invariant — it must ASK, not guess), the
// synthesizer MAY be repo-grounded: with repoPath it runs in a read-only throwaway
// worktree of HEAD, so the deliverable can cite real files and current shapes. Exported
// so --continue / --finalize can reuse it standalone over a saved debate.
export async function runFinalize(
  judge: Participant, quaestio: string, transcript: string, determination: string, repoPath?: string,
): Promise<Turn> {
  const r = await runIsolated(judge, finalizePrompt(quaestio, transcript, determination), repoPath);
  return { title: `Final report — ${judge.display}`, participant: judge.id, result: r };
}

// The continuation turn: re-judge after the human answered. Transcript-only, like respondeo.
export async function runContinuation(
  judge: Participant, quaestio: string, transcript: string, previousDetermination: string, humanAnswers: string,
): Promise<Turn> {
  const r = await runIsolated(judge, continuePrompt(quaestio, transcript, previousDetermination, humanAnswers));
  return { title: `Respondeo (continued) — ${judge.display}`, participant: judge.id, result: r };
}

export async function runDebate(
  task: string,
  participants: Participant[],
  rounds: number,
  repoPath?: string,
  judge?: Participant,
): Promise<DebateOutcome> {
  const header = `# Disputatio debate\n\n## Task\n\n${task}\n`;
  const fileParts: string[] = [header];
  const ctxParts: string[] = [header];
  const turns: Turn[] = [];

  const record = (title: string, p: Participant, r: AgentResult) => {
    turns.push({ title, participant: p.id, result: r });
    fileParts.push(render(title, r));
    ctxParts.push(renderForContext(title, r));
  };

  // Round 1 — independent proposals (parallel; each isolated so they don't peek).
  log(`Round 1 — independent proposals: ${participants.map((p) => p.id).join(", ")}`);
  const proposals = await Promise.all(
    participants.map(async (p) => ({ p, r: await runIsolated(p, proposePrompt(task), repoPath) })),
  );
  for (const { p, r } of proposals) record(`Proposal — ${p.display}`, p, r);

  // A debate needs at least two voices. Fewer than 2 successful proposals means
  // the surviving agent would "debate" a monologue — abort loudly instead of
  // producing a plausible-looking but worthless artifact (real-run lesson, 2026-06-11).
  const okProposals = proposals.filter(({ r }) => r.ok).length;
  if (okProposals < 2) {
    const failures = proposals
      .filter(({ r }) => !r.ok)
      .map(({ p, r }) => `${p.id}: ${(r as { error: string }).error}`)
      .join(" | ");
    const aborted = `only ${okProposals}/${participants.length} proposals succeeded — no debate possible. Failures: ${failures}`;
    log(`ABORTED — ${aborted}`);
    fileParts.push(`## Debate aborted\n\n> ⚠️ ${aborted}\n`);
    return { transcript: fileParts.join("\n"), turns, aborted };
  }

  // Reaction rounds — each participant reacts to the full transcript snapshot.
  for (let round = 1; round <= rounds; round++) {
    log(`Round ${round + 1} — reactions`);
    const ctx = ctxParts.join("\n");
    const reactions = await Promise.all(
      participants.map(async (p) => ({ p, r: await runIsolated(p, reactPrompt(ctx, p.display), repoPath) })),
    );
    for (const { p, r } of reactions) record(`Round ${round} reaction — ${p.display}`, p, r);
  }

  // Respondeo — opt-in judge turn (transcript-only: no repoPath, even in repo mode).
  // A failed judge is non-fatal: it's recorded, but the debate itself still succeeded.
  let respondeo: DebateOutcome["respondeo"];
  let finalReport: DebateOutcome["finalReport"];
  let finalReportError: DebateOutcome["finalReportError"];
  if (judge) {
    const debateCtx = ctxParts.join("\n"); // clean transcript snapshot BEFORE the respondeo turn
    log(`Respondeo — ${judge.display} renders the consolidatio`);
// Debate config (Kaizen v0): `--config debate.yaml` selects the participant
// lineup so each run can choose adapters that match the target repository policy.
//
// This parses a deliberately MINIMAL YAML subset — flat top-level scalars plus
// one `participants:` list of flat maps — with strict, line-numbered errors.
// No dependency, no build step (the repo's standing rule). When config needs
// real YAML (nesting, anchors), switch to a parser library; do not grow this.

export type AdapterId = "claude" | "agy" | "codex" | "pi" | "copilot-cli";

export type ParticipantSpec = {
  adapter: AdapterId;
  model?: string;        // omit = the adapter's default (codex: the account default)
  bin?: string;          // override the binary path (e.g. a shadowed codex install)
  maxBudgetUsd?: number; // claude only
  effort?: string;       // reasoning effort, to dose token spend. claude: --effort
                         // (low|medium|high|xhigh|max); codex: model_reasoning_effort
                         // (minimal|low|medium|high). NOT supported by agy (effort is
                         // baked into the model name, e.g. "Gemini 3.5 Flash (High)").
                         // Free-form string: the CLI validates it (errors surface in
                         // the raw capture / --doctor), so this parser stays version-agnostic.
};

export type DebateConfig = {
  rounds?: number;
  repo?: string;
  timeoutMinutes?: number;
  participants?: ParticipantSpec[];
  judge?: ParticipantSpec; // the respondeo agent: renders the consolidatio (opt-in)
};

// The inverse of parseDebateConfig: emit the same minimal YAML subset this module
// parses, so a generated config round-trips back through parseDebateConfig unchanged.
// Used by `disputatio --init` to write ~/.config/disputatio/config.yaml. Keep it in
// lock-step with the parser — if one grows a key, so must the other (round-trip test).
const PARTICIPANT_ORDER: (keyof ParticipantSpec)[] = ["adapter", "model", "bin", "maxBudgetUsd", "effort"];

// Quote a scalar only when leaving it bare would change how the parser reads it — namely
// edge whitespace or an empty value (both eaten by the parser otherwise). Plain values
// like model names with spaces/parens ("Gemini 3.5 Flash (High)") stay unquoted; the
// parser reads the whole rest-of-line. A value with a `(^|\s)#` is UNREPRESENTABLE — the
// parser strips trailing comments before handling quotes, so quoting can't save it; we
// refuse it loudly rather than write config that silently round-trips to something else.
function emitScalar(v: string | number): string {
  if (typeof v === "number") return String(v);
  if (/(^|\s)#/.test(v)) throw new Error(`config value cannot contain a "#" comment marker: ${JSON.stringify(v)}`);
  return v === "" || v !== v.trim() ? JSON.stringify(v) : v;
}

function emitSpec(spec: ParticipantSpec, indent: string, firstPrefix: string): string {
  const lines: string[] = [];
  let prefix = firstPrefix;
  for (const key of PARTICIPANT_ORDER) {
    const val = spec[key];
    if (val === undefined) continue;
    lines.push(`${prefix}${key}: ${emitScalar(val)}`);
    prefix = indent; // only the first key carries the "- " list marker
  }
  return lines.join("\n");
}

export function serializeDebateConfig(cfg: DebateConfig): string {
  const out: string[] = [];
  if (cfg.rounds !== undefined) out.push(`rounds: ${cfg.rounds}`);
  if (cfg.timeoutMinutes !== undefined) out.push(`timeoutMinutes: ${cfg.timeoutMinutes}`);
  if (cfg.repo !== undefined) out.push(`repo: ${emitScalar(cfg.repo)}`);
  if (cfg.participants) {
    out.push("participants:");
    for (const p of cfg.participants) out.push(emitSpec(p, "    ", "  - "));
  }
  if (cfg.judge) {
    out.push("judge:");
    out.push(emitSpec(cfg.judge, "  ", "  "));
  }
  return out.join("\n") + "\n";
}

const ADAPTERS = new Set<string>(["claude", "agy", "codex", "pi", "copilot-cli"]);
const TOP_KEYS = new Set<string>(["rounds", "repo", "timeoutMinutes", "participants", "judge"]);
const PARTICIPANT_KEYS = new Set<string>(["adapter", "model", "bin", "maxBudgetUsd", "effort"]);
const NUMERIC_KEYS = new Set<string>(["rounds", "timeoutMinutes", "maxBudgetUsd"]);

function fail(lineNo: number, msg: string): never {
  throw new Error(`debate config line ${lineNo}: ${msg}`);
}

function scalar(raw: string, key: string, lineNo: number): string | number {
  let v = raw.trim();
  const quoted = (v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"));
  if (quoted) v = v.slice(1, -1);
  if (v === "") fail(lineNo, `key "${key}" has no value`);
  if (NUMERIC_KEYS.has(key)) {
    const n = Number(v);
    if (!Number.isFinite(n)) fail(lineNo, `key "${key}" must be a number, got "${v}"`);
    return n;
  }
  return v;
}

export function parseDebateConfig(text: string): DebateConfig {
  const cfg: DebateConfig = {};
  let participants: Record<string, string | number>[] | null = null;
  // The judge is a single spec (not a list). The `in*` flags track which block's
  // continuation lines we are currently reading; any new top-level key closes both
  // (so the accumulators are NOT discarded — a later `judge:` must not drop the
  // already-parsed participants, nor a later top key the judge).
  let judge: Record<string, string | number> | null = null;
  let inParticipants = false;
  let inJudge = false;

  const lines = text.split("\n");
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1;
    const noComment = lines[i].replace(/(^|\s)#.*$/, ""); // strip full-line & trailing comments
    if (noComment.trim() === "") continue;

    const top = noComment.match(/^([A-Za-z][A-Za-z0-9]*):\s*(.*)$/);          // key: value (indent 0)
    const item = noComment.match(/^\s+-\s+([A-Za-z][A-Za-z0-9]*):\s*(.*)$/);  //   - key: value
    const cont = noComment.match(/^\s+([A-Za-z][A-Za-z0-9]*):\s*(.*)$/);      //     key: value

    if (top) {
      const [, key, rest] = top;
      if (!TOP_KEYS.has(key)) fail(lineNo, `unknown key "${key}" (known: ${[...TOP_KEYS].join(", ")})`);
      // A new top-level key always ends the current block (but keeps its accumulator).
      inParticipants = key === "participants";
      inJudge = key === "judge";
      if (key === "participants") {
        if (rest.trim() !== "") fail(lineNo, `"participants" must be a list (put items on the following lines)`);
        participants = [];
      } else if (key === "judge") {
        if (rest.trim() !== "") fail(lineNo, `"judge" must be a block (put its keys on the following indented lines)`);
        judge = {};
      } else {
        (cfg as Record<string, unknown>)[key] = scalar(rest, key, lineNo);
      }
    } else if (item && inParticipants && participants) {
      const [, key, rest] = item;
      if (!PARTICIPANT_KEYS.has(key)) fail(lineNo, `unknown participant key "${key}" (known: ${[...PARTICIPANT_KEYS].join(", ")})`);
      participants.push({ [key]: scalar(rest, key, lineNo) });
    } else if (cont && inParticipants && participants) {
      const [, key, rest] = cont;
      if (!PARTICIPANT_KEYS.has(key)) fail(lineNo, `unknown participant key "${key}" (known: ${[...PARTICIPANT_KEYS].join(", ")})`);
      const current = participants[participants.length - 1];
      if (!current) fail(lineNo, `participant field before any "- " list item`);
      if (key in current) fail(lineNo, `duplicate participant key "${key}"`);
      current[key] = scalar(rest, key, lineNo);
    } else if (cont && inJudge && judge) {
      const [, key, rest] = cont;
      if (!PARTICIPANT_KEYS.has(key)) fail(lineNo, `unknown participant key "${key}" (known: ${[...PARTICIPANT_KEYS].join(", ")})`);
      if (key in judge) fail(lineNo, `duplicate judge key "${key}"`);
      judge[key] = scalar(rest, key, lineNo);
    } else {
      fail(lineNo, `cannot parse "${lines[i].trim()}" (this parser supports only flat "key: value" and a participants list)`);
    }
  }

  if (participants) {
    for (const p of participants) {
      if (typeof p.adapter !== "string" || !ADAPTERS.has(p.adapter)) {
        throw new Error(`debate config: each participant needs "adapter: claude | agy | codex | pi | copilot-cli" (got ${JSON.stringify(p)})`);
      }
    }
    if (participants.length < 2) {
      throw new Error(`debate config: a debate needs at least 2 participants (got ${participants.length})`);
    }
    cfg.participants = participants as ParticipantSpec[];
  }
  if (judge) {
    if (typeof judge.adapter !== "string" || !ADAPTERS.has(judge.adapter)) {
      throw new Error(`debate config: the judge needs "adapter: claude | agy | codex | pi | copilot-cli" (got ${JSON.stringify(judge)})`);
    }
    cfg.judge = judge as ParticipantSpec;
  }
  if (cfg.rounds !== undefined && (!Number.isInteger(cfg.rounds) || cfg.rounds < 0)) {
    throw new Error(`debate config: "rounds" must be a non-negative integer`);
  }
  return cfg;
}
// Orchestration tests — fake in-process participants (no spawning), plus a REAL
// git repo in a temp dir to verify the read-only worktree isolation invariant.

import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, writeFile, readFile, rm } from "node:fs/promises";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { runDebate, runFinalize, runContinuation, parseRespondeoStatus } from "../src/debate.ts";
import type { Participant, AgentResult } from "../src/adapters.ts";

const execFileAsync = promisify(execFile);

function fake(id: string, vendor: string, run: Participant["run"]): Participant {
  return { id, vendor, display: id, run };
}
const ok = (text: string): AgentResult => ({ ok: true, text, costUsd: 0.5 });
const fail = (error: string): AgentResult => ({ ok: false, error });

test("abort: <2 successful proposals ends the debate before any reaction round", async () => {
  let reactions = 0;
  const a = fake("a", "v1", async (prompt) => {
    if (prompt.includes("debate so far")) reactions++;
    return ok("proposal A");
  });
  const b = fake("b", "v2", async () => fail("timeout"));
  const out = await runDebate("task", [a, b], 3);
  assert.ok(out.aborted);
  assert.match(out.aborted!, /only 1\/2 proposals succeeded/);
  assert.match(out.transcript, /Debate aborted/);
  assert.equal(reactions, 0);
});

test("abort: both proposals failing lists both failures", async () => {
  const a = fake("a", "v1", async () => fail("budget"));
  const b = fake("b", "v2", async () => fail("timeout"));
  const out = await runDebate("task", [a, b], 1);
  assert.ok(out.aborted);
  assert.match(out.aborted!, /a: budget/);
  assert.match(out.aborted!, /b: timeout/);
});

test("reaction context is clean: proposals included, cost footnotes excluded", async () => {
  const seen: string[] = [];
  const a = fake("a", "v1", async (prompt) => {
    if (prompt.includes("debate so far")) seen.push(prompt);
    return ok("proposal A says X");
  });
  const b = fake("b", "v2", async () => ok("proposal B says Y"));
  const out = await runDebate("task", [a, b], 1);
  assert.equal(out.aborted, undefined);
  assert.equal(seen.length, 1);
  assert.match(seen[0], /proposal A says X/);
  assert.match(seen[0], /proposal B says Y/);
  assert.doesNotMatch(seen[0], /cost:/);              // prompt hygiene
  assert.match(out.transcript, /cost: \$0\.5000/);    // …but the artifact keeps cost
  assert.equal(out.turns.length, 4);                  // 2 proposals + 2 reactions
});

test("respondeo: the judge runs after reactions and reads proposals + reactions", async () => {
  let judgePrompt = "";
  const a = fake("a", "v1", async () => ok("proposal A says X"));
  const b = fake("b", "v2", async () => ok("proposal B says Y"));
  const j = fake("opus", "v3", async (prompt) => {
    if (prompt.includes("You are the JUDGE")) judgePrompt = prompt; // capture the respondeo call, not the redactio
    return ok("STATUS: RESOLVED\n\nThe verdict.");
  });
  const out = await runDebate("task", [a, b], 1, undefined, j);
  assert.equal(out.aborted, undefined);
  // judge saw both proposals and the round-1 reactions
  assert.match(judgePrompt, /proposal A says X/);
  assert.match(judgePrompt, /Round 1 reaction/);
  assert.doesNotMatch(judgePrompt, /cost:/); // clean context, like reactions
  // recorded as a Respondeo turn in both turns[] and the transcript
  assert.match(out.transcript, /## Respondeo — opus/);
  assert.ok(out.turns.some((t) => t.title === "Respondeo — opus"));
  assert.equal(out.respondeo?.status, "RESOLVED");
  // …and a RESOLVED respondeo is now followed by the redactio (final deliverable)
  assert.equal(out.turns.at(-1)?.title, "Final report — opus");
  assert.ok(out.finalReport);
});

test("finalize: a RESOLVED respondeo triggers a final-report deliverable turn", async () => {
  let redactioPrompt = "";
  const a = fake("a", "v1", async () => ok("proposal A"));
  const b = fake("b", "v2", async () => ok("proposal B"));
  const j = fake("opus", "v3", async (prompt) => {
    if (prompt.includes("FINAL DELIVERABLE")) {
      redactioPrompt = prompt;
      return ok("# The Plan\n\nStep 1: do the thing.");
    }
    return ok("STATUS: RESOLVED\n\nRuling: X wins.");
  });
  const out = await runDebate("Build a thing", [a, b], 0, undefined, j);
  assert.equal(out.respondeo?.status, "RESOLVED");
  assert.ok(out.finalReport, "finalReport present on RESOLVED");
  assert.match(out.finalReport!.text, /The Plan/);
  // the synthesizer saw the quaestio, the transcript, and the determination
  assert.match(redactioPrompt, /Build a thing/);
  assert.match(redactioPrompt, /proposal A/);
  assert.match(redactioPrompt, /Ruling: X wins/);
  // recorded as the final turn + in the transcript artifact
  assert.equal(out.turns.at(-1)?.title, "Final report — opus");
  assert.match(out.transcript, /## Final report — opus/);
});

test("finalize: NEEDS_INPUT does not produce a final report (the deliverable waits for the human)", async () => {
  const a = fake("a", "v1", async () => ok("proposal A"));
  const b = fake("b", "v2", async () => ok("proposal B"));
  const j = fake("opus", "v3", async () => ok("STATUS: NEEDS_INPUT\n\n## Quaestiones (for the human)\n- ?"));
  const out = await runDebate("task", [a, b], 0, undefined, j);
  assert.equal(out.finalReport, undefined);
  assert.doesNotMatch(out.transcript, /Final report/);
});

test("finalize: no judge means no final report", async () => {
  const a = fake("a", "v1", async () => ok("proposal A"));
  const b = fake("b", "v2", async () => ok("proposal B"));
  const out = await runDebate("task", [a, b], 0); // no judge
  assert.equal(out.finalReport, undefined);
});

test("finalize: a failing redactio is non-fatal (debate + respondeo still succeeded)", async () => {
  const a = fake("a", "v1", async () => ok("proposal A"));
  const b = fake("b", "v2", async () => ok("proposal B"));
  const j = fake("opus", "v3", async (prompt) =>
    prompt.includes("FINAL DELIVERABLE") ? fail("budget") : ok("STATUS: RESOLVED\n\nRuling."),
  );
  const out = await runDebate("task", [a, b], 0, undefined, j);
  assert.equal(out.respondeo?.status, "RESOLVED");
  assert.equal(out.finalReport, undefined);                 // no deliverable captured
  assert.match(out.transcript, /## Final report — opus/);   // …but the failed turn is recorded
});

test("finalize: budget-exhausted redactio sets finalReportError.budgetExhausted", async () => {
  const budgetFail = (error: string): AgentResult => ({ ok: false, error, budgetExhausted: true });
  const a = fake("a", "v1", async () => ok("proposal A"));
  const b = fake("b", "v2", async () => ok("proposal B"));
  const j = fake("opus", "v3", async (prompt) =>
    prompt.includes("FINAL DELIVERABLE") ? budgetFail("Reached maximum budget ($2)") : ok("STATUS: RESOLVED\n\nRuling."),
  );
  const out = await runDebate("task", [a, b], 0, undefined, j);
  assert.equal(out.respondeo?.status, "RESOLVED");
  assert.equal(out.finalReport, undefined);
  assert.equal(out.finalReportError?.budgetExhausted, true);
  assert.match(out.finalReportError?.message ?? "", /Reached maximum budget/);
});

test("continuation: re-invokes the judge with the quaestio, transcript, prior determination, and human answers", async () => {
  let p = "";
  const j = fake("opus", "v3", async (prompt) => {
    p = prompt;
    return ok("STATUS: RESOLVED\n\nNow resolved with your answer.");
  });
  const turn = await runContinuation(j, "the quaestio", "TRANSCRIPT BODY", "PRIOR DETERMINATION", "the human answer");
  assert.match(p, /the quaestio/);
  assert.match(p, /TRANSCRIPT BODY/);
  assert.match(p, /PRIOR DETERMINATION/);
  assert.match(p, /the human answer/);
  assert.equal(turn.title, "Respondeo (continued) — opus");
  assert.ok(turn.result.ok);
  assert.equal(parseRespondeoStatus((turn.result as { text: string }).text), "RESOLVED");
});

test("continuation: degrades to NEEDS_INPUT when the answer opens ground the debaters never argued", async () => {
  const j = fake("opus", "v3", async () => ok("STATUS: NEEDS_INPUT\n\n## Quaestiones (for the human)\n- a new one"));
  const turn = await runContinuation(j, "q", "t", "prior", "answer that opens new ground");
  assert.ok(turn.result.ok);
  assert.equal(parseRespondeoStatus((turn.result as { text: string }).text), "NEEDS_INPUT");
});

test("respondeo: no judge turn when the judge arg is absent", async () => {
  const a = fake("a", "v1", async () => ok("proposal A"));
  const b = fake("b", "v2", async () => ok("proposal B"));
  const out = await runDebate("task", [a, b], 1); // no judge
  assert.equal(out.respondeo, undefined);
  assert.equal(out.turns.length, 4); // 2 proposals + 2 reactions, no respondeo
  assert.doesNotMatch(out.transcript, /Respondeo/);
});

test("respondeo: STATUS: NEEDS_INPUT surfaces on the outcome", async () => {
  const a = fake("a", "v1", async () => ok("proposal A"));
  const b = fake("b", "v2", async () => ok("proposal B"));
  const j = fake("opus", "v3", async () => ok("STATUS: NEEDS_INPUT\n\n## Quaestiones (for the human)\n- ?"));
  const out = await runDebate("task", [a, b], 0, undefined, j);
  assert.equal(out.respondeo?.status, "NEEDS_INPUT");
});

test("respondeo: a failing judge is non-fatal", async () => {
  const a = fake("a", "v1", async () => ok("proposal A"));
  const b = fake("b", "v2", async () => ok("proposal B"));
  const j = fake("opus", "v3", async () => fail("budget"));
  const out = await runDebate("task", [a, b], 0, undefined, j);
  assert.equal(out.aborted, undefined);          // debate still succeeded
  assert.equal(out.respondeo?.status, "FAILED");
  assert.match(out.transcript, /Respondeo — opus/); // failure still recorded
});

