    log(`ABORTED — ${aborted}`);
    fileParts.push(`## Debate aborted\n\n> ⚠️ ${aborted}\n`);
    return { transcript: fileParts.join("\n"), turns, aborted };
  }

  // Reaction rounds — each participant reacts to the full transcript snapshot.
  for (let round = 1; round <= rounds; round++) {
