import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdir, mkdtemp, readFile, rm, symlink, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, relative, resolve } from "node:path";
import { classifyDetermination, listDebates } from "../src/catalog.ts";

async function fixture(): Promise<{ base: string; root: string; outside: string }> {
  const base = await mkdtemp(join(tmpdir(), "disputatio-catalog-"));
  const root = join(base, "catalog");
  const outside = join(base, "outside");
  await Promise.all([mkdir(root), mkdir(outside)]);
  return { base, root, outside };
}

test("listDebates selects and sorts only immediate real debate directories", async () => {
  const { base, root } = await fixture();
  try {
    await Promise.all([
      mkdir(join(root, "debate-z")),
      mkdir(join(root, "debate-A")),
      mkdir(join(root, "debate-a.2")),
      mkdir(join(root, "debate-a-1")),
      mkdir(join(root, "debate-")),
      mkdir(join(root, "debate-_invalid")),
      mkdir(join(root, "debate-a!")),
      mkdir(join(root, "other")),
      writeFile(join(root, "debate-file"), "not a directory"),
      writeFile(join(root, "unrelated.txt"), "unrelated"),
    ]);
    await mkdir(join(root, "debate-A", "debate-nested"));

    const entries = await listDebates(root);

    assert.deepEqual(entries.map((entry) => entry.id), ["debate-A", "debate-a-1", "debate-a.2", "debate-z"]);
    assert.deepEqual(entries.map((entry) => entry.path), [
      join(root, "debate-A"),
      join(root, "debate-a-1"),
      join(root, "debate-a.2"),
      join(root, "debate-z"),
    ]);
  } finally {
    await rm(base, { recursive: true, force: true });
  }
});

test("listDebates checks transcript and final report independently", async () => {
  const { base, root } = await fixture();
  try {
    const transcript = join(root, "debate-1_transcript");
    const report = join(root, "debate-2_report");
    await Promise.all([mkdir(transcript), mkdir(report)]);
    await Promise.all([
      writeFile(join(transcript, "debate.md"), ""),
      writeFile(join(report, "final-report.md"), ""),
    ]);

    assert.deepEqual(await listDebates(root), [
      {
        id: "debate-1_transcript", path: transcript, hasTranscript: true, hasFinalReport: false,
        determination: null, status: "unjudged",
      },
      {
        id: "debate-2_report", path: report, hasTranscript: false, hasFinalReport: true,
        determination: null, status: "unjudged",
      },
    ]);
  } finally {
    await rm(base, { recursive: true, force: true });
  }
});

test("listDebates recognizes only regular local artifacts and excludes directory symlinks", async () => {
  const { base, root, outside } = await fixture();
  try {
    const complete = join(root, "debate-complete");
    const linkedArtifacts = join(root, "debate-linked-artifacts");
    const directoryArtifacts = join(root, "debate-directory-artifacts");
    const linkedChildTarget = join(outside, "debate-real-child");
    await Promise.all([
      mkdir(complete),
      mkdir(linkedArtifacts),
      mkdir(directoryArtifacts),
      mkdir(linkedChildTarget),
      writeFile(join(outside, "transcript.md"), "outside transcript"),
      writeFile(join(outside, "report.md"), "outside report"),
    ]);
    await Promise.all([
      writeFile(join(complete, "debate.md"), "transcript"),
      writeFile(join(complete, "final-report.md"), "report"),
      symlink(join(outside, "transcript.md"), join(linkedArtifacts, "debate.md")),
      symlink(join(outside, "report.md"), join(linkedArtifacts, "final-report.md")),
      mkdir(join(directoryArtifacts, "debate.md")),
      mkdir(join(directoryArtifacts, "final-report.md")),
      symlink(linkedChildTarget, join(root, "debate-linked-child")),
    ]);

    const entries = await listDebates(root);

    assert.deepEqual(entries, [
      {
        id: "debate-complete", path: complete, hasTranscript: true, hasFinalReport: true,
        determination: null, status: "unjudged",
      },
      {
        id: "debate-directory-artifacts", path: directoryArtifacts, hasTranscript: false, hasFinalReport: false,
        determination: null, status: "unjudged",
      },
      {
        id: "debate-linked-artifacts", path: linkedArtifacts, hasTranscript: false, hasFinalReport: false,
        determination: null, status: "unjudged",
      },
    ]);
    assert.equal(await readFile(join(outside, "transcript.md"), "utf8"), "outside transcript");
    assert.equal(await readFile(join(outside, "report.md"), "utf8"), "outside report");
  } finally {
    await rm(base, { recursive: true, force: true });
  }
});

test("listDebates returns an empty array for a missing root and resolves relative roots", async () => {
  const { base, root } = await fixture();
  try {
    const debate = join(root, "debate-relative");
    await mkdir(debate);

    assert.deepEqual(await listDebates(join(base, "missing")), []);

    const relativeRoot = relative(process.cwd(), root);
    assert.deepEqual(await listDebates(relativeRoot), [
      {
        id: "debate-relative", path: resolve(root, "debate-relative"), hasTranscript: false, hasFinalReport: false,
        determination: null, status: "unjudged",
      },
    ]);
  } finally {
    await rm(base, { recursive: true, force: true });
  }
});

test("classifyDetermination uses only the first nonempty trimmed line and strict markers", () => {
  assert.equal(classifyDetermination("\n  STATUS: RESOLVED  \nbody"), "resolved");
  assert.equal(classifyDetermination("\nSTATUS: NEEDS_INPUT\n- question"), "needs-input");
  assert.equal(classifyDetermination("  Respondeo turn failed: budget exhausted"), "failed");
  assert.equal(classifyDetermination("\r\n \t\r\nSTATUS: RESOLVED\r\nbody"), "resolved");
  assert.equal(classifyDetermination("Respondeo turn failed:"), "failed");

  assert.equal(classifyDetermination(""), "unknown");
  assert.equal(classifyDetermination(" \t\n\r\n"), "unknown");
  assert.equal(classifyDetermination("STATUS:RESOLVED"), "unknown");
  assert.equal(classifyDetermination("STATUS:  NEEDS_INPUT"), "unknown");
  assert.equal(classifyDetermination("STATUS: resolved"), "unknown");
  assert.equal(classifyDetermination("Respondeo turn failed"), "unknown");
  assert.equal(classifyDetermination("STATUS: RESOLVED because reasons"), "unknown");
  assert.equal(classifyDetermination("status: RESOLVED"), "unknown");
  assert.equal(classifyDetermination("STATUS: NEEDS_INPUT?"), "unknown");
  assert.equal(classifyDetermination("first line\nSTATUS: RESOLVED"), "unknown");
  assert.equal(classifyDetermination("respondeo turn failed: lowercase"), "unknown");
});

test("listDebates reports each determination status and chooses the largest numeric version", async () => {
  const { base, root } = await fixture();
  try {
    const unjudged = join(root, "debate-unjudged");
    const resolved = join(root, "debate-resolved");
    const needsInput = join(root, "debate-needs-input");
    const failed = join(root, "debate-failed");
    const unknown = join(root, "debate-unknown");
    const versions = join(root, "debate-versions");
    await Promise.all([unjudged, resolved, needsInput, failed, unknown, versions].map((path) => mkdir(path)));
    await Promise.all([
      writeFile(join(resolved, "respondeo.md"), "STATUS: RESOLVED\n"),
      writeFile(join(needsInput, "respondeo-2.md"), "\n STATUS: NEEDS_INPUT \n"),
      writeFile(join(failed, "respondeo.md"), "Respondeo turn failed: the judge timed out"),
      writeFile(join(unknown, "respondeo.md"), "The judge gave no status."),
      writeFile(join(versions, "respondeo-2.md"), "STATUS: RESOLVED"),
      writeFile(join(versions, "respondeo-10.md"), "STATUS: NEEDS_INPUT"),
    ]);

    const entries = await listDebates(root);

    assert.deepEqual(entries.map(({ id, determination, status }) => ({ id, determination, status })), [
      { id: "debate-failed", determination: "respondeo.md", status: "failed" },
      { id: "debate-needs-input", determination: "respondeo-2.md", status: "needs-input" },
      { id: "debate-resolved", determination: "respondeo.md", status: "resolved" },
      { id: "debate-unjudged", determination: null, status: "unjudged" },
      { id: "debate-unknown", determination: "respondeo.md", status: "unknown" },
      { id: "debate-versions", determination: "respondeo-10.md", status: "needs-input" },
    ]);
  } finally {
    await rm(base, { recursive: true, force: true });
  }
});

test("listDebates accepts arbitrarily large positive versions and breaks equal versions by filename", async () => {
  const { base, root } = await fixture();
  try {
    const huge = join(root, "debate-huge");
    const tied = join(root, "debate-tied");
    const invalid = join(root, "debate-invalid");
    const smallerHugeVersion = "9".repeat(80);
    const largerHugeVersion = `1${"0".repeat(80)}`;
    await Promise.all([mkdir(huge), mkdir(tied), mkdir(invalid)]);
    await Promise.all([
      writeFile(join(huge, `respondeo-${smallerHugeVersion}.md`), "STATUS: RESOLVED"),
      writeFile(join(huge, `respondeo-${largerHugeVersion}.md`), "STATUS: NEEDS_INPUT"),
      writeFile(join(tied, "respondeo.md"), "STATUS: RESOLVED"),
      writeFile(join(tied, "respondeo-01.md"), "STATUS: NEEDS_INPUT"),
      writeFile(join(invalid, "respondeo-0.md"), "STATUS: RESOLVED"),
      writeFile(join(invalid, "respondeo--1.md"), "STATUS: RESOLVED"),
      writeFile(join(invalid, "respondeo-1.5.md"), "STATUS: RESOLVED"),
      writeFile(join(invalid, "respondeo-1x.md"), "STATUS: RESOLVED"),
      writeFile(join(invalid, "respondeo-.md"), "STATUS: RESOLVED"),
    ]);

    const entries = await listDebates(root);

    assert.deepEqual(entries.map(({ id, determination, status }) => ({ id, determination, status })), [
      { id: "debate-huge", determination: `respondeo-${largerHugeVersion}.md`, status: "needs-input" },
      { id: "debate-invalid", determination: null, status: "unjudged" },
      { id: "debate-tied", determination: "respondeo-01.md", status: "needs-input" },
    ]);
  } finally {
    await rm(base, { recursive: true, force: true });
  }
});

test("listDebates ignores determination directories and links, including a higher linked version", async () => {
  const { base, root, outside } = await fixture();
  try {
    const regular = join(root, "debate-regular");
    const onlyLinks = join(root, "debate-only-links");
    await Promise.all([mkdir(regular), mkdir(onlyLinks)]);
    await writeFile(join(outside, "respondeo.md"), "STATUS: NEEDS_INPUT");
    await Promise.all([
      writeFile(join(regular, "respondeo-2.md"), "STATUS: RESOLVED"),
      symlink(join(outside, "respondeo.md"), join(regular, "respondeo-999.md")),
      mkdir(join(regular, "respondeo-1000.md")),
      symlink(join(outside, "respondeo.md"), join(onlyLinks, "respondeo.md")),
      symlink(join(outside, "respondeo.md"), join(onlyLinks, "respondeo-999.md")),
    ]);

    const entries = await listDebates(root);

    assert.deepEqual(entries.map(({ id, determination, status }) => ({ id, determination, status })), [
      { id: "debate-only-links", determination: null, status: "unjudged" },
      { id: "debate-regular", determination: "respondeo-2.md", status: "resolved" },
    ]);
    assert.equal(await readFile(join(outside, "respondeo.md"), "utf8"), "STATUS: NEEDS_INPUT");
  } finally {
    await rm(base, { recursive: true, force: true });
  }
});

