test("listDebates rejects invalid pagination options before checking the root", async () => {
  const { base, root } = await fixture();
  try {
    const invalidOptions: unknown[] = [
      { offset: -1 }, { limit: -1 }, { offset: 1.5 }, { limit: 1.5 },
      { offset: NaN }, { limit: NaN }, { offset: Infinity }, { limit: Infinity },
      { offset: "1" }, { limit: "1" }, { offset: null }, { limit: null },
      { offset: true }, { limit: false },
    ];
    for (const options of invalidOptions) {
      await assert.rejects(() => listDebates(root, options as never), (error: unknown) => {
        assert.equal((error as { code?: unknown }).code, "INVALID_QUERY");
        return true;
      });
    }
    await assert.rejects(() => listDebates(join(base, "missing"), { offset: -1, limit: 0 }), (error: unknown) => {
      assert.equal((error as { code?: unknown }).code, "INVALID_QUERY");
      return true;
    });
    assert.deepEqual(await listDebates(join(base, "missing"), { limit: 0 }), []);
  } finally {
    await rm(base, { recursive: true, force: true });
  }
});

test("listDebates filters every status and regular final reports with AND semantics", async () => {
  const { base, root, outside } = await fixture();
  try {
    const unjudged = join(root, "debate-z-unjudged");
    const resolved = join(root, "debate-y-resolved");
    const needsInput = join(root, "debate-x-needs-input");
    const failed = join(root, "debate-w-failed");
    const unknown = join(root, "debate-v-unknown");
    await Promise.all([unjudged, resolved, needsInput, failed, unknown].map((path) => mkdir(path)));
    await writeFile(join(outside, "final-report.md"), "outside report");
    await Promise.all([
      symlink(join(outside, "final-report.md"), join(unjudged, "final-report.md")),
      writeFile(join(resolved, "respondeo.md"), "STATUS: RESOLVED"),
      writeFile(join(resolved, "final-report.md"), "report"),
      writeFile(join(needsInput, "respondeo.md"), "STATUS: NEEDS_INPUT"),
      writeFile(join(failed, "respondeo.md"), "Respondeo turn failed: budget"),
      writeFile(join(failed, "final-report.md"), "report"),
      writeFile(join(unknown, "respondeo.md"), "no marker"),
    ]);

    const ids = async (options?: ListDebatesOptions) =>
      (await listDebates(root, options)).map((entry) => entry.id);

    const everyId = ["debate-z-unjudged", "debate-y-resolved", "debate-x-needs-input", "debate-w-failed", "debate-v-unknown"];
    assert.deepEqual(await ids(), everyId);
    assert.deepEqual(await ids({}), everyId);
    assert.deepEqual(await ids({ status: undefined, hasFinalReport: undefined }), everyId);
    assert.deepEqual(await ids({ status: "unjudged" }), ["debate-z-unjudged"]);
    assert.deepEqual(await ids({ status: "resolved" }), ["debate-y-resolved"]);
    assert.deepEqual(await ids({ status: "needs-input" }), ["debate-x-needs-input"]);
    assert.deepEqual(await ids({ status: "failed" }), ["debate-w-failed"]);
    assert.deepEqual(await ids({ status: "unknown" }), ["debate-v-unknown"]);
    assert.deepEqual(await ids({ hasFinalReport: true }), ["debate-y-resolved", "debate-w-failed"]);
    assert.deepEqual(await ids({ hasFinalReport: false }), ["debate-z-unjudged", "debate-x-needs-input", "debate-v-unknown"]);
    assert.deepEqual(await ids({ status: "resolved", hasFinalReport: true }), ["debate-y-resolved"]);
    assert.deepEqual(await ids({ status: "resolved", hasFinalReport: false }), []);
    assert.deepEqual(await ids({ status: "unjudged", hasFinalReport: false }), ["debate-z-unjudged"]);
    assert.equal(await readFile(join(outside, "final-report.md"), "utf8"), "outside report");
  } finally {
    await rm(base, { recursive: true, force: true });
  }
});

test("listDebates paginates before filtering without backfilling later matches", async () => {
  const { base, root } = await fixture();
  try {
    const newest = join(root, "debate-z-newest");
    const firstMatch = join(root, "debate-y-first-match");
    const laterMatch = join(root, "debate-x-later-match");
    await Promise.all([mkdir(newest), mkdir(firstMatch), mkdir(laterMatch)]);
    await Promise.all([
      writeFile(join(firstMatch, "respondeo.md"), "STATUS: RESOLVED"),
      writeFile(join(laterMatch, "respondeo.md"), "STATUS: RESOLVED"),
      writeFile(join(firstMatch, "final-report.md"), "report"),
      writeFile(join(laterMatch, "final-report.md"), "report"),
    ]);

    assert.deepEqual((await listDebates(root, { limit: 1, status: "resolved" })).map((entry) => entry.id), []);
    assert.deepEqual((await listDebates(root, { limit: 2, status: "resolved" })).map((entry) => entry.id), [
      "debate-y-first-match",
    ]);
    assert.deepEqual((await listDebates(root, { offset: 1, limit: 1, status: "resolved" })).map((entry) => entry.id), [
      "debate-y-first-match",
    ]);
    assert.deepEqual(await listDebates(root, { limit: 1, hasFinalReport: true }), []);
    assert.deepEqual((await listDebates(root, { limit: 2, hasFinalReport: true })).map((entry) => entry.id), [
      "debate-y-first-match",
    ]);
    assert.deepEqual((await listDebates(root, { offset: 1, limit: 1, hasFinalReport: true })).map((entry) => entry.id), [
      "debate-y-first-match",
    ]);
  } finally {
    await rm(base, { recursive: true, force: true });
  }
});

test("listDebates validates supplied filters before zero-limit and missing-root shortcuts", async () => {
  const { base, root } = await fixture();
  try {
      throw Object.assign(new Error(`${name} must be a nonnegative integer`), { code: "INVALID_QUERY" });
    }
  }
  if (status !== undefined && !["unjudged", "resolved", "needs-input", "failed", "unknown"].includes(status)) {
    throw Object.assign(new Error("status must be a catalog status"), { code: "INVALID_QUERY" });
  }
  if (hasFinalReport !== undefined && typeof hasFinalReport !== "boolean") {
    throw Object.assign(new Error("hasFinalReport must be a boolean"), { code: "INVALID_QUERY" });
  }
  if (limit === 0) return [];

  const absoluteRoot = resolve(root);
  let children: Dirent[];

  try {
    children = await readdir(absoluteRoot, { withFileTypes: true });
  } catch (error: unknown) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw error;
  }

  const directories = children
    .filter((child) => child.isDirectory() && DEBATE_DIR.test(child.name))
    .map((child) => child.name)
    .sort()
    .reverse();

  const entries = await Promise.all(directories.map(async (id) => {
    const path = join(absoluteRoot, id);
    const [hasTranscript, hasFinalReport, metadata] = await Promise.all([
      isRegularFile(join(path, "debate.md")),
      isRegularFile(join(path, "final-report.md")),
      determinationMetadata(path),
    ]);
    return { id, path, hasTranscript, hasFinalReport, ...metadata };
  }));

  // Offset and limit count matching debates, not unfiltered directory positions.
  return entries.filter((entry) =>
    (status === undefined || entry.status === status) &&
    (hasFinalReport === undefined || entry.hasFinalReport === hasFinalReport))
    .slice(offset)
    .slice(0, limit);
}

